-- Tabla `postulaciones_estudiantes`
DROP TABLE IF EXISTS `postulaciones_estudiantes`;
CREATE TABLE `postulaciones_estudiantes` (
    `id` INT NOT NULL AUTO_INCREMENT,
    `id_investigacion` INT NOT NULL,
