    NEW.`id`,
    'INSERT',
    CAST(NULLIF(@app_usuario_actual, '') AS SIGNED),
    NULL,
    JSON_OBJECT('titulo', NEW.`titulo`, 'id_tipo_recurso', NEW.`id_tipo_recurso`),
    CURRENT_TIMESTAMP
);

