(8, 7, 'Propuesta de un modelo de implementación basado en aprendizaje automático para el reclutamiento de profesionales de ingeniería en una universidad pública', 'IAIAIAIAIAIA', 'https://revistas.unal.edu.co/public/journals/21/cover_issue_5423_es_ES.png', 'publicado', 70.00, '2026-11-03 00:12:27', '2026-11-03 00:15:32', 'propuesta-de-un-modelo-de-implementaci-n-basado-en-aprendizaje-autom-tico-para-el-reclutamiento-de-profesionales-de-ingenier-a-en-una-universidad-p-blica', 'https://www.youtube.com/watch?v=1rXVRH1Ne1Q', 'Presencial', 'Intermedio', '123123 semanas', 1231231, '2026-11-01', '2026-11-19', '', 'Cerrada', NULL);
